HugeWindowBase.example:
#include "kernel/arch/x86_64/page_entry.hpp"

using namespace cinux::arch::page;

constexpr uint64_t kWindow = HugeWindowBase(0x1'2345'6789ULL);
// kWindow = 0x1'0000'0000 · 4 GiB 处开始的 1 GB 窗口
static_assert(kWindow == 0x1'0000'0000ULL);

MakeTableEntry.example:
#include "kernel/arch/x86_64/page_entry.hpp"

using namespace cinux::arch::page;

constexpr Entry kNextTable = MakeTableEntry(0x40'0000ULL, kWritable);
// raw = 0x400003 · 存在位、可写位和下一级表的 4 KiB 帧地址
static_assert(kNextTable.raw == 0x400003);

PlanDeviceDoors.example:
#include "kernel/arch/x86_64/page_entry.hpp"

using namespace cinux::arch::page;

constexpr DoorSpan kDoors = PlanDeviceDoors(0xFD00'0000ULL, 0x0400'0000ULL);
// first_index = 3 · count = 2 · 64 MiB 帧缓冲跨过 4 GiB 边界
static_assert(kDoors.first_index == 3 && kDoors.count == 2);
